steps:
{"step":2,
 "conflict_matrix":[
   {"issue":"즉시 전면차단 vs 패치 전 서비스 유지","security_gain":"추가 비인가 접근 즉시 차단, 피해 확산 방지","privacy_loss":"서비스 중단으로 인한 정보주체 불편, 탐지 사실 조기 노출 시 내부자 증거인멸 가능성 증가","level":"MED"},
   {"issue":"즉시 통지 vs 조사 완료 후 통지","security_gain":"조사 비노출로 내부자 행위 패턴 추가 확보, 침해 범위 정확히 확정 후 정밀 대응 가능","privacy_loss":"정보주체의 알 권리 지연, 법정 통지기한(72시간 등) 도과 위험, 권리행사(열람정정 등) 기회 상실","level":"HIGH"},
   {"issue":"'유출' 해당 여부 법적 불확실성","security_gain":"법적 불확실성 핑계로 통지 보류 시 조사 시간 확보","privacy_loss":"단건이라도 '유출'로 해석될 경우 미통지는 법 위반, 정보주체 피해 인지 지연","level":"HIGH"},
   {"issue":"전면차단(운영) vs 최소권한 회수","security_gain":"전면차단은 확실한 차단이나 업무 마비·포렌식 증거 훼손 우려","privacy_loss":"최소권한 회수는 운영 지속 가능하나 유사 경로의 추가 비인가 조회 가능성 잔존","level":"MED"}
 ],
 "hard_constraints":[
   "개인정보보호법 제34조: '유출'로 판단될 경우 지체없이(통상 72시간 이내) 정보주체 통지 및 일정 규모 이상 시 개인정보보호위원회 신고 의무 (단, 본건이 '유출'에 해당하는지는 법령·판례 확인 필요, 확정 불가)",
   "ISMS-P 3.4: 침해사고 대응절차상 탐지-분석-대응-보고 단계별 기록 및 적시 보고 요구 (구체적 시점 기준은 내부 정책·인증기준 재확인 필요)"
 ],
 "self_check":{
   "if_security_first":"패치 완료까지 통지를 미루면, 법정 통지기한을 도과하여 개인정보보호법 제34조 위반 소지가 발생하고, 정보주체는 본인 정보 열람 사실을 알지 못한 채 권리행사 기회를 상실함. 추후 사실 공개 시 '은폐 시도'로 비춰져 신뢰도·법적 책임이 가중될 위험.",
   "if_privacy_first":"조사 미완료 상태에서 즉시 전면 공개·차단하면, 내부자가 증거를 인멸하거나 책임 회피 행동을 할 수 있고, 침해 범위가 확정되지 않은 채 통지하여 부정확한 정보 제공(과소/과대 통지) 위험이 있으며, 전면차단으로 정상 업무 마비 및 패치 전 취약점 정보가 외부에 노출되어 유사 공격을 유발할 가능성."
 },
 "mitigations":[
   "비인가 조회 로그는 가명화/최소필드만 분석팀에 제공 (조회자·대상자 ID 마스킹)",
   "보안팀(차단·조사)과 개인정보보호책임자(통지여부 판단)의 승인권한 분리 및 공동 의사결정 프로세스화",
   "전면차단 대신 해당 계정·권한만 즉시 회수(최소권한 조치)하여 업무 연속성과 차단 효과 동시 확보",
   "내부 비공개 조사와 별개로 '법적 유출 해당여부'를 법무/DPO가 24시간 내 1차 판단하여 통지의무 발생 시 즉시 정보주체·감독기관에 선통지, 세부 경위는 조사 완료 후 추가 공지",
   "로그 보존기간 및 접근기록은 변경불가(WORM) 저장소에 즉시 백업하여 증거보전과 투명성 동시 확보"
 ]
}

{"experiment_condition":"B_UNIFIED_3STEP","scenario_id":"CFL-08",
 "final_decision":"전면차단·전사공지 대신 '해당 계정·권한의 즉시 최소권한 회수 + 로그 증거보전'을 선조치하고, 법무/DPO가 24시간 내 '개인정보보호법 제34조상 유출 해당여부'를 1차 판단하여 유출 해당 시 정보주체·감독기관에 지체없이(패치 완료를 기다리지 않고) 통지한다. 패치는 통지와 병행하여 최대한 신속히 진행하되 통지 지연 사유로 사용하지 않는다.",
 "decision_status":"CONDITIONAL_APPROVE",
 "conflicts_identified":[
   {"axis":"legal","issue":"단건 비인가 조회가 개인정보보호법 제34조상 '유출'에 해당하는지 불명확한 상태에서 통지시점을 패치완료까지 미룰 경우 법정 통지기한(지체없이/72시간 등) 도과 위험","security_gain":"조사 완료 후 정확한 범위로 통지 가능","privacy_loss":"정보주체의 알 권리·권리행사 기회 지연, 법 위반 시 제재 및 신뢰 손상","resolution":"법무/DPO가 24시간 내 유출해당여부 선판단, 해당 시 패치완료 전이라도 선통지(세부경위는 추후 보완공지)"},
   {"axis":"technical","issue":"전면차단은 침해 확산을 확실히 막지만 포렌식 증거(세션/메모리) 훼손 및 패치 전 취약점 노출 가능성, 반면 비공개 유지는 동일 경로 추가 비인가 조회 위험 존속","security_gain":"전면차단 시 추가 피해 확실히 차단","privacy_loss":"전면차단 시 업무마비로 정당한 정보주체 서비스 접근까지 차단되는 부수피해, 비공개 유지 시 추가 조회 위험으로 피해 확산","resolution":"전면차단 대신 문제 계정·권한만 즉시 회수(최소권한), 로그는 WORM 저장소에 즉시 백업하여 증거보전과 서비스연속성 동시 확보"},
   {"axis":"operational","issue":"즉시 전사 공지 시 조사 미완료 상태의 부정확한 정보 전달(과소/과대 통지) 및 내부자 증거인멸·도주 유발 가능, 반대로 비공개 유지 시 '은폐 시도'로 비칠 리스크 및 보안팀-개인정보보호팀 간 의사결정 권한 충돌","security_gain":"비공개 조사로 내부자 행위패턴 추가 확보 및 정밀 대응","privacy_loss":"통지 지연에 따른 투명성 결여, 추후 공개 시 신뢰도 추가 손상","resolution":"보안팀(차단·조사)과 DPO(통지판단) 권한 분리 후 공동 의사결정 프로세스화, 1차 최소정보 선통지 후 조사완료시 상세공지로 단계적 커뮤니케이션"}
 ],
 "required_controls":{
   "security":["문제 계정·권한 즉시 회수(최소권한 조치)","접근로그 WORM 저장소 즉시 백업 및 무결성 보존","영향범위(접근 대상 레코드) 긴급 스코핑 분석","유사 권한 보유 계정 전수 점검"],
   "privacy":["법무/DPO 24시간 내 유출해당여부 1차 판단","해당 시 정보주체에 최소정보로 선통지, 조사완료 후 상세경위 추가공지","필요시 개인정보보호위원회 신고 기한 준수","조회 로그 분석 시 조회자/대상자 ID 가명화 처리"]
 },
 "residual_risk":{"security":"medium","privacy":"medium"},
 "risk_owner":"CISO-CPO 공동(법무/DPO 1차판단권, 보안팀 조치실행권 분리)",
 "bias_self_check":{
   "if_only_privacy":"보안 조사 없이 즉시 전면공지·전면차단만 했다면 내부자 증거인멸 유발 및 침해범위 미확정 상태의 부정확한 통지로 오히려 2차 신뢰손상 위험이 커졌을 것",
   "if_only_security":"패치완료까지 비공개를 유지했다면 법정 통지기한 도과로 제34조 위반 및 과징금·신뢰손상 위험이 현실화되었을 것"
 },
 "bias_direction":"balanced","confidence":0.62}
